mapper.body:
{
  "model": "anthropic/claude-sonnet-4-6",
  "messages": [
    {
      "role": "system",
      "content": "Write short professional reminder emails."
    },
    {
      "role": "user",
      "content": "Write a 3-sentence reminder for {{1.body.payload.invitee.name}} about their appointment {{1.body.payload.event_type.name}} tomorrow. Mention they can reply to reschedule. Return only the email body."
    }
  ],
  "temperature": 0.5,
  "max_tokens": 300
}

{
  "properties": {
    "hs_timestamp": "{{now}}",
    "hs_note_body": "Reminder sent to {{1.body.payload.invitee.email}} 24 hours before appointment. Subject: Your appointment tomorrow. Sent at {{formatDate(now; \"YYYY-MM-DD HH:mm:ss\"; \"America/New_York\")}} Eastern Time. Calendly event: {{1.body.payload.event_type.name}}. Invitee: {{1.body.payload.invitee.name}}. Event start time: {{1.body.payload.event.start_time}}."
  }
}

{
  "from": "{{env.CWI_ALERT_FROM_ADDRESS}}",
  "to": ["{{env.ADMIN_EMAIL}}"],
  "subject": "[ALERT] Appointment Reminder — Error in Scenario M",
  "text": "Scenario M (Appointment Reminder) encountered an error.

Failed Module: {{errorHandler.moduleId}}
Error Type: {{errorHandler.type}}
Error Message: {{errorHandler.message}}
Timestamp: {{formatDate(now; "YYYY-MM-DD HH:mm:ss"; "America/New_York")}} Eastern

Invitee Name: {{1.body.payload.invitee.name}}
Invitee Email: {{1.body.payload.invitee.email}}
Calendly Event: {{1.body.payload.event_type.name}}
Event Start Time: {{1.body.payload.event.start_time}}

Please send the reminder manually or follow up with the invitee."
}
